frappe.ui.form.on('Payment Entry', {
    party: function(frm) {
        if (frm.doc.party_type == 'Supplier' && frm.doc.party) {
            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Supplier",
                    name: frm.doc.party
                },
                callback: function(r) {
                    if(r.message) {
                        frm.set_value('custom_beneficiary_bank_name', r.message.custom_beneficiary_bank_name_);
                        frm.set_value('custom_beneficiary_account_name', r.message.custom_beneficiary_account_name);
                        frm.set_value('custom_beneficiary_account_number', r.message.custom_beneficiary_account_number);
                    }
