refresh: function(frm) {
        if (frm.is_new()) {
            frm.add_custom_button(__('Get Invoice'), function() {
                insertItemsFromPurchaseInvoice(frm);
            });
        }
    }
});

function insertItemsFromPurchaseInvoice(frm) {
    if (!frm.doc.invoice) {
        frappe.msgprint('Please select an invoice first');
        return;
    }

    frappe.db.get_doc('Purchase Invoice', frm.doc.invoice)
        .then(function(invoice) {
            frm.set_value('court_name', invoice.custom_court);
            frm.set_value('account_name', invoice.custom_beneficiary_account_name);
            frm.set_value('invoice', invoice.name);
            frm.set_value('supplier', invoice.supplier);
            frm.set_value('account_number', invoice.custom_landlord_account_number);
            frm.set_value('bank', invoice.custom_landlord_bank_name);
            frm.set_value('tenant_name', invoice.custom_customer_name);
            frm.set_value('amount_figures', invoice.outstanding_amount);

            // Convert outstanding_amount to words
            var amountInWords = convertAmountToWords(invoice.outstanding_amount);
            frm.set_value('amount_in_word', amountInWords);
        })
        .catch(function(err) {
            frappe.msgprint('Error: ' + err);
        });
}

function convertAmountToWords(amount) {
