frappe.ui.form.on('Investment App', {
    refresh: function(frm) {
        // A flag to check if the form has already been reloaded
        if (frm.doc.__is_reload_done) {
            return;  // Exit if the form has already been reloaded
        }

        // Check if transaction_type is already set
        if (frm.doc.transaction_type) {
            let workflow_name = 'Investment App (Request for Payment) Workflow';
            let is_active = frm.doc.transaction_type === 'Request for Payments' ? 1 : 0;  // Set is_active based on transaction_type

            // Call the Python function to update the workflow's is_active status
            frappe.call({
                method: 'loan_investment_app.custom_api.workflow.update_workflow_to_active',
                args: {
                    workflow_name: workflow_name,
                    is_active: is_active
                },
                callback: function(response) {
                    // Check the response to see if the workflow was updated
                    if (response.message) {
                        frappe.msgprint(response.message);
                    }

                    // Save the document after updating the workflow
                    frm.save().then(() => {
                        // Set the flag to indicate the form has been reloaded
                        frm.doc.__is_reload_done = true;

                        // No need to reload the document here
                        // frm.reload_doc(); // Removed this line to avoid reloading
                    }).catch((error) => {
