// Function to convert number to words
function numberToWords(num) {
    const ones = [
        "", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine",
        "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen",
        "Seventeen", "Eighteen", "Nineteen"
    ];
    const tens = [
        "", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"
    ];
    const thousands = [
        "", "Thousand", "Million", "Billion"
    ];

    if (num === 0) return "Zero";

    let word = "";
    let i = 0;

    while (num > 0) {
        const chunk = num % 1000;
        if (chunk > 0) {
            const chunkWord = convertChunk(chunk);
            word = chunkWord + (thousands[i] ? " " + thousands[i] : "") + " " + word;
        }
        num = Math.floor(num / 1000);
        i++;
    }

    return word.trim();

    function convertChunk(num) {
        let chunkWord = "";

        if (num > 99) {
            chunkWord += ones[Math.floor(num / 100)] + " Hundred ";
            num %= 100;
        }
        if (num > 19) {
            chunkWord += tens[Math.floor(num / 10)] + " ";
            num %= 10;
        }
        if (num > 0) {
            chunkWord += ones[num] + " ";
        }

        return chunkWord.trim();
    }
}

// Function to format amount as currency
function formatAmount(amount) {
    const formattedAmount = "₦" + amount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    const amountInWords = numberToWords(Math.floor(amount));
    return `${formattedAmount} (${amountInWords} Naira Only)`;
}

